const DASHBOARD_URL = 'https://app.getelliot.eu';
const d = $json;
const n = (x) => Number(x || 0);
const plural = (count, one, many) => `${count} ${count === 1 ? one : many}`;
const lines = [];
lines.push(`Good morning ${d.recipient_name},`);
lines.push('');
lines.push(`In the last 24 hours Elliot had ${plural(n(d.conversations_count), 'conversation', 'conversations')}, ` +
  `captured ${plural(n(d.new_leads_count), 'new lead', 'new leads')} and booked ${plural(n(d.viewings_booked_count), 'viewing', 'viewings')}.`);
const today = d.viewings_today || [];
lines.push('');
if (today.length) {
  lines.push(`Viewings today (${today.length}):`);
  today.forEach(v => lines.push(`  ${v.time}  ${v.name}${v.notes ? ' -- ' + v.notes : ''}`));
} else {
  lines.push('No viewings booked for today.');
}
const hot = d.hot_leads || [];
if (hot.length) {
  lines.push('');
  lines.push(`Hot leads waiting for a call (${n(d.hot_leads_count)}):`);
  hot.forEach(h => lines.push(`  ${h.name}${h.phone ? ', ' + h.phone : ''}${h.email ? ', ' + h.email : ''}`));
}
const todo = [];
if (n(d.open_escalations)) todo.push(plural(n(d.open_escalations), 'conversation needs a person', 'conversations need a person'));
if (n(d.pending_approvals)) todo.push(plural(n(d.pending_approvals), 'email is waiting for approval', 'emails are waiting for approval'));
if (todo.length) {
  lines.push('');
  lines.push('Needs you: ' + todo.join(', ') + '.');
}
lines.push('');
lines.push(`Open the dashboard: ${DASHBOARD_URL}`);
lines.push('');
lines.push('You get this because daily summaries are on for you in Elliot (Team page).');
const subject = `[Elliot] ${d.tenant_name}: ${plural(n(d.new_leads_count), 'new lead', 'new leads')}, ${plural(today.length, 'viewing', 'viewings')} today`;
const raw =
  `To: ${d.recipient_email}\r\n` +
  `Subject: ${subject}\r\n` +
  `Content-Type: text/plain; charset=UTF-8\r\n\r\n` +
  lines.join('\n');
const encoded = Buffer.from(raw).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return { json: { tenant_id: d.tenant_id, recipient_email: d.recipient_email, raw_message: encoded } };
